const kind = (a1, b1, c1, a2, b2, c2) => { const det = a1 * b2 - a2 * b1; if (Math.abs(det) > 1e-12) return 'unica'; return Math.abs(a1 * c2 - a2 * c1) < 1e-12 && Math.abs(b1 * c2 - b2 * c1) < 1e-12 ? 'infinitas' : 'ninguna'; };
