const f = (x, b, c) => Math.log(x) / Math.log(b) + c;
const bs = []; for (let i = 101; i <= 2000; i++) bs.push(i / 100);
const cs = [-1, 0, 2, 3.5];
const b1 = new Set(); for (const b of bs) for (const c of cs) if (Math.abs(f(b, b, c) - 3) < 1e-9) b1.add(b);
const b2 = new Set(); for (const b of bs) for (const c of cs) if (Math.abs(f(9, b, c) - f(3, b, c) - 0.5) < 1e-9) b2.add(b);
const b12 = new Set(); for (const b of bs) for (const c of cs) if (Math.abs(f(b, b, c) - 3) < 1e-9 && Math.abs(f(9, b, c) - f(3, b, c) - 0.5) < 1e-9) b12.add(b);
const s1 = b1.size === 1, s2 = b2.size === 1, s12 = b12.size === 1;
if (s1 && s2) return 'D'; if (s1) return 'A'; if (s2) return 'B'; if (s12) return 'C'; return 'E';

